effect.shader:
mat2 rot2m(float a){
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
vec2 l2s( vec2 v ) {
return (vec4(v,0.,1.)*acLayerToScreen).xy;
}
float sat( float t ) {
return clamp( t, 0.0, 1.0 );
}
vec2 sat( vec2 t ) {
return clamp( t, 0.0, 1.0 );
}
float remap  ( float t, float a, float b ) {
return sat( (t - a) / (b - a) );
}
float linterp( float t ) {
return sat( 1.0 - abs( 2.0*t - 1.0 ) );
}
vec3 spectrum_offset( float t ) {
float t0 = 3.0 * t - 1.5;
return clamp( vec3( -t0, 1.0-abs(t0), t0), 0.0, 1.0);
}
float rand( vec2 n ) {
return fract(sin(dot(n.xy, vec2(12.9898, 78.233)))* 43758.5453);
}
float srand( vec2 n ) {
return rand(n) * 2.0 - 1.0;
}
float mytrunc( float x, float num_levels )
{
return floor(x*num_levels) / num_levels;
}
vec2 mytrunc( vec2 x, float num_levels )
{
return floor(x*num_levels) / num_levels;
}
void main ()
{
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
vec2 syamjaidtz;
syamjaidtz = acScreenNorm;
vec4 result;
float aspect = acScreenSize.x / acScreenSize.y;
vec2 uv = syamjaidtz;
float time = mod(progressa, 32.0);
float GLITCH = 0.1 + 0.0 / syamjaidtz.x;
float gnm = sat( GLITCH );
float rnd0 = rand( mytrunc( vec2(time, time), 6.0 ) );
float r0 = sat((1.0-gnm)*0.7 + rnd0);
float rnd1 = rand( vec2(mytrunc( uv.x, 10.0*r0 ), time) );
float r1 = 0.5 - 0.5 * gnm + rnd1;
r1 = 1.0 - max( 0.0, ((r1<1.0) ? r1 : 0.9999999) );
float rnd2 = rand( vec2(mytrunc( uv.y, 40.0*r1 ), time) );
float r2 = sat( rnd2 );
float rnd3 = rand( vec2(mytrunc( uv.y, 10.0*r0 ), time) );
float r3 = (1.0-sat(rnd3+0.8)) - 0.1;
float pxrnd = rand( uv + time );
float ofs = 0.05 * r2 * GLITCH * ( rnd0 > 0.5 ? 1.0 : -1.0 );
ofs += 0.5 * pxrnd * ofs;
uv.y += 0.1 * r3 * GLITCH;
float RCP_NUM_SAMPLES_F = 1.0 / AMOUNT;
vec4 sum = vec4(0.0);
vec3 wsum = vec3(0.0);
for( int i=0; i<int(AMOUNT); ++i )
{
float t = float(i) * RCP_NUM_SAMPLES_F;
uv.x = sat( uv.x + ofs * t );
vec4 samplecol = texture2DCv( inputImg.texture, uv);
vec3 s = spectrum_offset( t );
samplecol.rgb = samplecol.rgb * s;
sum += samplecol;
wsum += s;
}
sum.rgb /= wsum;
sum.a *= RCP_NUM_SAMPLES_F;
result.a = sum.a;
result.rgb = sum.rgb;
vec4 factor = mix(texColorX,result,1.0);
vec4 resultfinal = (factor * 1.0) * texColor.a;
gl_FragColor = mix(texColor,resultfinal,alpha);
}
